                             </div>
                         )}
                    </div>
                    <div className="p-4">
                        <h4 className="text-white font-bold truncate">{reel.caption}</h4>
                        <p className="text-xs text-gray-400">{reel.client}</p>
                    </div>
                </div>
            ))}
        </div>
      </div>
    </section>
  );
};

