import { DriveVideo } from '../types';

interface PortfolioDriveProps {
  isAdmin: boolean;
}

const DEFAULT_VIDEOS: DriveVideo[] = [
  { 
    id: '1', 
    driveId: '1kcRj9QdAO1EMY7H5wno4HUexhgut2aGr', 
    title: 'Casamento: Kathelen & Gean', 
    category: 'Casamento' 
  },
  { 
    id: '2', 
    driveId: '1BXHON8h2UQjykxBLsmYQfC6MhZdoVVuS', 
    title: 'Casamento: Cerimônia Completa', 
    category: 'Casamento' 
  },
  { 
    id: '3', 
    driveId: '1AagfPT9MDPoMxwWpK0Dxez18pT44OHtA', 
    title: 'Casamento: Melhores Momentos', 
    category: 'Casamento' 
  },
];

const LOCAL_STORAGE_KEY = 'guizera_drive_videos_v20';

const PortfolioDrive: React.FC<PortfolioDriveProps> = ({ isAdmin }) => {
  const [videos, setVideos] = useState<DriveVideo[]>(DEFAULT_VIDEOS);
  const [inputUrl, setInputUrl] = useState('');
  const [category, setCategory] = useState('Casamento');
  const [error, setError] = useState('');

  // Player state
  const [selectedVideo, setSelectedVideo] = useState<DriveVideo | null>(null);
  const [isVideoLoading, setIsVideoLoading] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        setVideos(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved videos", e);
        setVideos(DEFAULT_VIDEOS);
      }
    } else {
        setVideos(DEFAULT_VIDEOS);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(videos));
  }, [videos]);

  const handleAddVideo = () => {
    setError('');
    const driveId = extractDriveId(inputUrl);

    if (!driveId) {
      setError('Link inválido. Certifique-se de que é um link de visualização do Google Drive.');
      return;
    }

    const newVideo: DriveVideo = {
      id: Date.now().toString(),
      driveId,
      title: `Projeto ${videos.length + 1}`,
      category: category || 'Geral'
    };

    setVideos([newVideo, ...videos]);
    setInputUrl('');
  };

  const handleDeleteVideo = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Tem certeza que deseja remover este vídeo?')) {
      setVideos(videos.filter(v => v.id !== id));
    }
  };

  const openModal = (video: DriveVideo) => {
    setIsVideoLoading(true);
    setSelectedVideo(video);
    document.body.style.overflow = 'hidden';
  };

  const closeModal = () => {
    setSelectedVideo(null);
    setIsVideoLoading(false);
    document.body.style.overflow = 'unset';
  };

  return (
    <section id="portfolio" className="py-24 bg-black border-t border-white/5">
      <div className="container mx-auto px-6">
        <div className="mb-16 border-l-2 border-white pl-6">
          <h2 className="text-3xl md:text-5xl font-heading font-light text-white uppercase tracking-widest mb-2">Portfolio <span className="font-bold">Select</span></h2>
          <p className="text-gray-500 font-light tracking-wide uppercase text-sm">
            Cinematografia Digital de Alta Performance
          </p>
        </div>

        {/* Input Area - Only Visible to Admin */}
        {isAdmin && (
          <div className="max-w-3xl mx-auto bg-white/5 border border-white/10 rounded-none p-6 mb-16 relative">
            <div className="absolute top-0 right-0 bg-white text-black text-xs font-bold px-3 py-1">ADMIN</div>
            <h3 className="text-white font-bold mb-4 flex items-center gap-2 uppercase tracking-wider text-sm">
              <Plus size={16} /> Adicionar Vídeo
            </h3>
            <div className="flex flex-col md:flex-row gap-4">
              <input 
                type="text" 
                placeholder="Cole o link do Google Drive aqui..." 
                className="flex-1 bg-black border border-white/20 px-4 py-3 text-white focus:outline-none focus:border-white transition-colors"
                value={inputUrl}
                onChange={(e) => setInputUrl(e.target.value)}
              />
              <input 
                type="text"
                placeholder="Categoria"
                className="w-full md:w-48 bg-black border border-white/20 px-4 py-3 text-white focus:outline-none focus:border-white transition-colors"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              />
              <button 
                onClick={handleAddVideo}
                className="bg-white hover:bg-gray-200 text-black font-bold px-6 py-3 transition-colors whitespace-nowrap uppercase tracking-widest text-xs"
              >
                Adicionar
              </button>
            </div>
            {error && <p className="text-red-400 text-sm mt-2">{error}</p>}
          </div>
        )}

        {/* Video Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-1">
          {videos.map((video) => (
            <div 
                key={video.id} 
                className="group relative cursor-pointer aspect-video bg-[#050505] overflow-hidden"
                onClick={() => openModal(video)}
            >
              {isAdmin && (
                <button 
                  onClick={(e) => handleDeleteVideo(video.id, e)}
                  className="absolute top-2 right-2 z-30 bg-red-600 p-2 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <Trash2 size={16} className="text-white" />
                </button>
              )}

              {/* Thumbnail */}
              <div className="absolute inset-0 opacity-70 group-hover:opacity-40 transition-all duration-500 grayscale group-hover:grayscale-0">
                  <iframe
                    src={getDriveEmbedUrl(video.driveId)}
                    className="w-full h-full object-cover pointer-events-none"
                    title={video.title}
                    tabIndex={-1}
                    loading="lazy"
                  ></iframe>
              </div>

              {/* Click Guard */}
              <div className="absolute inset-0 z-20"></div>

              {/* Overlay Content */}
              <div className="absolute inset-0 z-10 flex flex-col items-center justify-center">
                  {/* Title appears on hover */}
                  <div className="opacity-0 group-hover:opacity-100 transition-all duration-500 transform translate-y-4 group-hover:translate-y-0 text-center p-4">
                      <span className="text-[10px] font-bold text-white uppercase tracking-[0.2em] mb-2 block">{video.category}</span>
                      <h3 className="text-white font-heading font-light text-xl uppercase tracking-wider">{video.title}</h3>
                      <div className="w-8 h-px bg-white mx-auto mt-4"></div>
                  </div>
              </div>

              {/* Corner accent */}
              <div className="absolute bottom-0 left-0 w-2 h-2 border-b border-l border-white/50 opacity-0 group-hover:opacity-100 transition-opacity m-4"></div>
              <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-white/50 opacity-0 group-hover:opacity-100 transition-opacity m-4"></div>
            </div>
          ))}
        </div>
      </div>

      {/* Lightbox Modal */}
      {selectedVideo && (
        <div 
            className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-0 md:p-10 animate-fade-in backdrop-blur-md"
            onClick={closeModal}
        >
            <div 
                className="relative w-full h-full flex flex-col items-center justify-center"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Top Actions Bar */}
                <div className="absolute top-4 right-4 z-50 flex gap-4">
                    <a 
                      href={getDriveEmbedUrl(selectedVideo.driveId).replace('/preview', '/view')} 
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-2 text-white/50 hover:text-white text-xs uppercase tracking-widest transition-colors"
                    >
                        <ExternalLink size={14} />
                        Drive
                    </a>

                    <button 
                        onClick={closeModal}
                        className="text-white hover:text-red-500 transition-colors"
                    >
                        <X size={32} strokeWidth={1} />
                    </button>
                </div>

                {/* Video Container */}
                <div className="w-full h-full max-w-7xl max-h-[80vh] bg-black shadow-2xl relative flex items-center justify-center border border-white/10">

                    {isVideoLoading && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center z-0 bg-black">
                            <Loader2 className="w-10 h-10 text-white/20 animate-spin mb-4" />
                        </div>
                    )}

                    <iframe
                        key={selectedVideo.id} 
                        src={getDriveEmbedUrl(selectedVideo.driveId)} 
                        className="w-full h-full relative z-10 bg-black"
                        onLoad={() => setIsVideoLoading(false)}
                        allow="autoplay; fullscreen; picture-in-picture"
                        allowFullScreen
                        title={selectedVideo.title}
                    ></iframe>
                </div>

                <div className="mt-6 text-center">
                    <h3 className="text-white font-light text-2xl uppercase tracking-widest">{selectedVideo.title}</h3>
                </div>
            </div>
        </div>
      )}
    </section>
  );
};

export default PortfolioDrive;

