            <a 
                href="https://instagram.com/guizerafilms" 
                target="_blank" 
                rel="noreferrer"
                className="mt-4 md:mt-0 flex items-center gap-2 text-white/60 hover:text-white transition-colors text-sm uppercase tracking-wider"
            >
                <Instagram size={16} />
                @guizerafilms
            </a>
        </div>

        {/* Input Area - Only Visible to Admin */}
        {isAdmin && (
          <div className="bg-white/5 border border-white/10 p-6 mb-12 relative">
             <div className="absolute top-0 left-0 bg-white text-black text-xs font-bold px-3 py-1">ADMIN MODE</div>
