                      value={inputUrl}
                      onChange={(e) => setInputUrl(e.target.value)}
                  />
               </div>
               <div className="flex-1 w-full">
                  <label className="text-xs text-gray-400 mb-1 block uppercase tracking-wide">Legenda</label>
                  <input 
                      type="text" 
                      placeholder="Nome do projeto" 
                      className="w-full bg-black border border-white/20 px-4 py-2 text-white focus:outline-none focus:border-white rounded-none"
                      value={caption}
                      onChange={(e) => setCaption(e.target.value)}
                  />
               </div>
               <button 
                  onClick={handleAddReel}
                  className="w-full md:w-auto bg-white hover:bg-gray-200 text-black px-6 py-2 flex items-center justify-center gap-2 transition-colors h-[42px] font-bold uppercase tracking-wider text-xs"
