                    <div className="p-4 border-t border-white/5">
                        <h4 className="text-white font-medium truncate text-sm uppercase tracking-wide">{reel.caption}</h4>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest mt-1">{reel.client}</p>
