export interface PortfolioVideo {
  id: string;
  embedId: string; // ID do arquivo no Drive ou ID do vídeo no Youtube
  title: string;
  category: string;
  url: string; // URL original completa
  platform: 'youtube' | 'drive';
}

export interface InstaVideo {
  id: string;
